WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM n WHERE i < 40)
WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM n WHERE i < 30)
UPDATE celda SET estado = 'MANTENIMIENTO' WHERE codigo = 'A-33';





UPDATE celda SET estado = 'OCUPADA' WHERE id_celda IN (SELECT id_celda FROM movimiento WHERE fecha_hora_salida IS NULL);
